<script setup>
import {resetStudioParameters} from '../../shared/parameter-defaults.mjs';
import {ref,computed,onMounted,onActivated,nextTick,watch} from 'vue';
import {MonitorCheck,RefreshCw,Download,FolderOpen,Upload,ChevronDown,Check,AlertCircle,ExternalLink,Terminal,Package,ShieldCheck,Languages,Save,LoaderCircle} from 'lucide-vue-next';
import {useStudio,api} from '../store';
import DownloadCenter from './DownloadCenter.vue';
import NetworkSettings from './NetworkSettings.vue';
import CacheSettings from './CacheSettings.vue';
import PathSettings from './PathSettings.vue';
import FileSettings from './FileSettings.vue';
import UpdateCenter from './UpdateCenter.vue';
import LlmSettings from './LlmSettings.vue';
import OperationGuide from './OperationGuide.vue';
import {about} from '../../shared/about.mjs';
const s=useStudio(),checking=ref(false),packages=ref([]),packageName=ref('ultralytics'),versions=ref([]),packageVersion=ref(''),mirror=ref('official'),snapshot=ref(null),showPackageManager=ref(false);const desktop=!!window.desktop;
const translationInfo=ref(null),translationChecking=ref(false);
async function refreshTranslationStatus(){translationChecking.value=true;try{translationInfo.value=await api('translate/status');}finally{translationChecking.value=false;}}
const translationBackups=computed({get:()=>(s.config.translatorBackups||[]).join('\n'),set:v=>s.config.translatorBackups=v.split(/\r?\n/).map(u=>u.trim()).filter(Boolean).slice(0,3)});
const category=computed({get:()=>s.config.settingsCategory||'general',set:value=>s.config.settingsCategory=value});
async function focusDownload(){if(category.value!=='environment'||!s.config.downloadFocusToken)return;await nextTick();document.getElementById('runtime-download')?.scrollIntoView({block:'center',behavior:'smooth'});}
watch(()=>s.config.downloadFocusToken,focusDownload);onActivated(focusDownload);
const categories=[{id:'general',name:'通用与界面'},{id:'content',name:'内容与成人限制'},{id:'network',name:'网络与代理连接'},{id:'storage',name:'缓存与存储'},{id:'files',name:'文件与本地位置'},{id:'environment',name:'电脑环境与运行时'},{id:'models',name:'生图模型与下载'},{id:'assistant',name:'提示词助手 / AI 接口'},{id:'guide',name:'操作说明与快捷键'},{id:'updates',name:'更新与卸载'},{id:'about',name:'关于软件'}];
const folders=computed(()=>[{kind:'diffusion_models',title:s.t('生图模型','Diffusion models'),desc:'Anima / Anima 2.9B'},{kind:'text_encoders',title:s.t('文本编码器','Text encoders'),desc:'Qwen3 0.6B'},{kind:'vae',title:'VAE',desc:s.t('图像编码与解码','Image encoding / decoding')},{kind:'loras',title:s.t('可选 LoRA','Optional LoRAs'),desc:s.t('角色与画风，默认不加载','Character / style, disabled by default')},{kind:'controlnet',title:s.t('局部重绘 ControlNet','Inpaint ControlNet'),desc:'局部重绘辅助模型'},{kind:'upscale_models',title:s.t('放大模型','Upscale models'),desc:'RealESRGAN / AnimeSharp'},{kind:'detectors',title:s.t('脸部与手部检测模型','Face / hand detectors'),desc:'YOLO / Ultralytics'}]);
async function openDependency(item){if(['vc','driver'].includes(item.link)){const result=await api('environment/download',{id:item.link});await s.openLink(item.link);s.notify(result.direct?'已打开适合这台电脑的官方下载：'+result.name:'已打开厂商自动检测页面：'+result.name);}else await s.openLink(item.link);}
async function check(){checking.value=true;await s.action(()=>s.checkEnvironment());checking.value=false;}
async function importModel(kind){if(!desktop){s.notify(s.t('请在桌面版选择模型文件，或将文件放进对应目录','Import model files in the desktop app'));return;}await s.action(async()=>{await window.desktop.pickModels(kind);s.models=await api('models');s.notify(s.t('模型已导入','Model imported'));});}
async function listPackages(){await s.action(async()=>{packages.value=await api('runtime/packages');});}
async function findVersions(){await s.action(async()=>{versions.value=await api('runtime/versions',{name:packageName.value});packageVersion.value=versions.value[0]||'';});}
async function installPackage(){await s.action(async()=>{await api('runtime/package/install',{name:packageName.value,version:packageVersion.value,mirror:mirror.value});s.notify(s.t('安装已开始，请查看日志','Installation started. See the log.'));});}
onMounted(()=>{void s.action(refreshTranslationStatus);if(!s.environment)void check();});
</script>
<template><div class="settings-layout" v-resize-panels="{key:'settings',config:s.config,min:[140,350],labels:['调整设置分类宽度']}"><nav class="settings-categories"><button v-for="item in categories" :class="{active:category===item.id}" @click="category=item.id">{{item.name}}</button></nav><div class="settings-workspace settings-content"><section v-show="category==='general'" class="card preference-card"><div class="card-heading"><div><Languages :size="18"/><strong>{{s.t('界面与使用偏好','Preferences')}}</strong></div></div><div class="settings-body"><div class="setting-row"><div><strong>{{s.t('界面语言','Language')}}</strong><p>{{s.t('切换界面显示语言','Choose your interface language')}}</p></div><div class="segmented"><button :class="{active:s.config.language==='zh'}" @click="s.config.language='zh'">简体中文</button><button :class="{active:s.config.language==='en'}" @click="s.config.language='en'">English</button></div></div><div class="setting-row"><div><strong>{{s.t('显存模式','Memory mode')}}</strong><p>{{s.t('修改后重启生图引擎生效。低显存模式适合较小的显卡。','Restart the engine after changing. Low VRAM mode uses less GPU memory.')}}</p></div><select v-model="s.config.memoryMode"><option value="auto">{{s.t('自动（推荐）','Automatic (recommended)')}}</option><option value="low">{{s.t('低显存模式','Low VRAM')}}</option><option value="cpu">{{s.t('CPU 模式（很慢）','CPU (slow)')}}</option></select></div><div class="setting-row"><div><strong>生成后释放模型资源</strong><p>每张图完成后卸载模型；队列结束后关闭空闲引擎，释放它占用的显存和内存。再次生成时自动启动。</p></div><label class="inline-check"><input type="checkbox" v-model="s.config.autoUnloadModels"/>自动释放（推荐）</label></div><div class="setting-row"><div><strong>漫画清晰模式</strong><p>为分镜生成时自动避免前景虚化，使用清晰线条；不改变官方采样参数。需要景深效果时可关闭。</p></div><label class="inline-check"><input type="checkbox" :checked="s.config.comicClarity!==false" @change="s.config.comicClarity=$event.target.checked"/>自动适配（推荐）</label></div><div class="setting-row"><div><strong>恢复所有创作参数</strong><p>恢复两种模型、当前项目分镜的生图/重绘、脸部/手部修复、放大和助手生成参数。保留提示词、图片、主模型/编码器/VAE 选择和密钥。</p></div><button class="secondary" @click="resetStudioParameters(s.config,s.project);s.notify('已恢复所有创作参数')">恢复所有参数</button></div><details class="advanced"><summary>{{s.t('自动翻译设置','Translation settings')}}<ChevronDown :size="16"/></summary><div class="advanced-content"><p class="info-note">常用标签优先查词库；完整描述自动选择已配置的翻译来源。服务超时、报错或译文无效时会自动切换备用，暂时跳过故障来源。DeepSeek 使用已保存的 Key，可能产生 API 费用。</p><label>首选翻译来源<select v-model="s.config.translationPreferred"><option value="auto">自动选择（推荐）</option><option value="deepseek">优先 DeepSeek</option><option value="offline">优先离线模型</option><option value="local">优先本地翻译服务</option></select></label><label class="inline-check"><input type="checkbox" v-model="s.config.translationCloud"/>允许使用已配置的 DeepSeek 翻译</label><div class="button-row"><button class="secondary" :disabled="translationChecking" :aria-busy="translationChecking" @click="s.action(refreshTranslationStatus)"><RefreshCw :size="15"/>刷新翻译状态</button><span v-if="translationInfo?.last" class="muted">最近使用：{{translationInfo.last.source}}{{translationInfo.last.fallback?' · 已自动切换备用':''}}</span></div><div v-if="translationInfo" class="translation-provider-list"><span>本地标签词库 · 可用</span><span v-for="p in translationInfo.providers">{{p.name}} · {{p.coolingDown?'暂时跳过，稍后自动重试':'已配置'}}</span><small>未下载的离线模型及未设置 Key 的线上接口会自动跳过；本地地址会在翻译时检查连接。</small></div><div class="button-row"><button class="secondary" @click="s.action(()=>api('models/download',{profile:'translation'}))" :disabled="s.install.state==='running'">{{s.t('下载离线中文翻译模型','Download offline translator')}}</button><button class="secondary" @click="s.action(()=>api('models/download',{profile:'tag_translation'}))" :disabled="s.install.state==='running'">下载离线标签翻译模型</button></div><label>{{s.t('本地翻译服务地址（备用）','Local endpoint (fallback)')}}<input v-model="s.config.translatorUrl" placeholder="http://127.0.0.1:5001/translate"/></label><label>其他本地备用服务（每行一个，按顺序尝试）<textarea v-model="translationBackups" rows="2" placeholder="http://127.0.0.1:5002/translate"/></label><label class="inline-check"><input type="checkbox" v-model="s.config.autoTranslate"/>{{s.t('生成前自动翻译中文','Translate Chinese before generation')}}</label></div></details></div></section>
 <PathSettings v-if="category==='environment'"/><p v-if="s.environmentError&&category==='environment'" class="error-note">{{s.environmentError}} · 已安装项目不会因此标记为未安装。</p><NetworkSettings v-if="category==='network'"/><details id="runtime-download" :class="{'download-highlight':category==='environment'&&s.config.downloadFocusToken}" v-show="category==='environment'" class="card settings-section" open><summary><div class="section-title"><MonitorCheck :size="20"/><div><strong>{{s.t('电脑环境与安装向导','Environment & installation')}}</strong><small>{{s.t('软件专用环境，不修改系统 Python','Dedicated environment, separate from system Python')}}</small></div></div><span :class="['environment-result',{ready:s.environment?.torch.available}]">{{s.environment?.torch.available?s.t('GPU 推理可用','GPU available'):s.t('需要检查','Check required')}}</span><ChevronDown :size="17"/></summary><div class="settings-body"><div class="button-row"><button class="secondary" @click="check" :disabled="checking"><RefreshCw :size="16" :class="{spin:checking}"/>{{checking?s.t('正在检查…','Checking…'):s.t('重新检测电脑','Check computer')}}</button><button class="primary" @click="s.action(()=>api('runtime/install',{}))" :disabled="s.install.state==='running'"><Download :size="16"/>{{s.t('安装 / 修复独立环境','Install / repair environment')}}</button><button class="secondary" @click="s.startEngine()" :disabled="s.engine.state==='starting'">{{s.t('启动引擎','Start engine')}}</button><button v-if="s.engine.state==='ready'" class="secondary" @click="s.action(()=>api('engine/stop',{}))">{{s.t('停止引擎','Stop engine')}}</button></div><div class="environment-grid"><article v-for="item in s.environment?.checks" :key="item.id" :class="['environment-card',item.state]"><span class="check-state" :class="item.state">{{item.state==='ok'?'✓':item.state==='optional'?'i':'!'}}</span><div><strong>{{item.name}}</strong><p>{{item.detail}}</p><div v-if="item.link&&item.state!=='ok'" class="button-row"><button class="text-button" @click="s.action(()=>openDependency(item))">{{s.t('自动选择并打开官方下载','Find official download')}}<ExternalLink :size="13"/></button><button v-if="item.id==='vc'" class="text-button" @click="s.action(()=>api('runtime/vc/install',{}))">{{s.t('下载并安装','Download & install')}}</button></div></div></article></div><div class="info-note"><ShieldCheck :size="17"/>{{s.t('首次下载需要网络和足够的磁盘空间。环境和模型准备完成后，生图与漫画排版可离线使用。显卡驱动请从厂商官网下载。','The first setup needs internet access and disk space. Generation and layout work offline once installed. Download GPU drivers from the vendor.')}}</div><div v-if="s.install.state!=='idle'" :class="['install-progress',s.install.state]"><div><LoaderCircle v-if="s.install.state==='running'" :size="16" class="spin"/><strong>{{s.install.message}}</strong><span>{{s.install.percent||0}}%</span></div><div class="download-file-name" v-if="s.install.name">{{s.install.name}} <span>{{s.install.fileIndex||1}} / {{s.install.fileCount||1}}</span></div><div class="progress download-progress"><i :style="{width:(s.install.percent||0)+'%'}"/></div><div v-if="s.install.total" class="download-stats"><span>{{((s.install.bytes||0)/1024/1024).toFixed(1)}} / {{(s.install.total/1024/1024).toFixed(1)}} MB</span><span>{{s.install.phase==='verifying'?s.t('正在校验 SHA256…','Verifying SHA256…'):s.install.speed?((s.install.speed/1024/1024).toFixed(1)+' MB/s') : ''}}</span><span v-if="s.install.eta">{{s.t('预计剩余','Remaining')}} {{Math.ceil(s.install.eta/60)}} {{s.t('分钟','min')}}</span></div><p v-if="s.install.fileCount>1" class="muted">{{s.t('全部文件','All files')}} {{s.install.overallPercent||0}}%</p></div><details class="tutorial"><summary>{{s.t('无法自动安装？查看手动步骤','Manual setup instructions')}}<ChevronDown :size="15"/></summary><ol><li>{{s.t('缺少 Visual C++：点击微软官方下载，运行 vc_redist.x64.exe，选择安装，完成后重启软件。','Missing Visual C++: download vc_redist.x64.exe from Microsoft, install it, then restart.')}}</li><li>{{s.t('GPU 不可用：更新 NVIDIA 显卡驱动并重启电脑；重新检测。Toolkit 未安装不代表不能生图。','GPU unavailable: update the NVIDIA driver and restart. Missing Toolkit does not mean inference is unavailable.')}}</li><li>{{s.t('Python / ComfyUI 缺失：点击上方安装按钮。下载失败时检查网络后重试，日志会显示具体步骤。','Missing Python / ComfyUI: use the installer above. If downloads fail, check the network and retry.')}}</li><li>{{s.t('显存不足：切换低显存模式，重启引擎，将图片尺寸降低到 1024×1024，并关闭修复与放大。','Out of VRAM: choose Low VRAM, restart the engine, reduce resolution to 1024×1024 and turn off finishing tools.')}}</li></ol></details>
  <details class="advanced" @toggle="showPackageManager=$event.target.open;if(showPackageManager)listPackages()"><summary><Package :size="16"/>{{s.t('高级：独立 Python 库管理','Advanced: Python packages')}}<ChevronDown :size="16"/></summary><div class="advanced-content"><p class="info-note">{{s.t('仅修改软件自己的 Python。安装前先停止生图引擎；初学者通常只需要上方的一键修复。','Changes apply only to this app. Stop the engine first. Beginners should use the repair button.')}}</p><div class="parameter-grid"><label>{{s.t('库名称','Package')}}<select v-model="packageName"><option v-for="p in ['torch','torchvision','transformers','safetensors','ultralytics','opencv-python','numpy','pillow','sentencepiece','torchsde']" :value="p">{{p}}</option></select></label><label>{{s.t('版本','Version')}}<select v-model="packageVersion"><option value="">{{s.t('最新版','Latest')}}</option><option v-for="v in versions" :value="v">{{v}}</option></select></label><label>{{s.t('下载源','Download source')}}<select v-model="mirror"><option value="official">{{s.t('官方','Official')}}</option><option value="tsinghua">{{s.t('清华镜像','Tsinghua mirror')}}</option></select></label></div><div class="button-row"><button class="secondary" @click="findVersions">{{s.t('查询可用版本','Find versions')}}</button><button class="secondary" @click="installPackage">{{s.t('安装选中的库','Install package')}}</button><button class="secondary" @click="listPackages">{{s.t('列出已安装库','List packages')}}</button><button class="secondary" @click="s.action(async()=>{snapshot=await api('runtime/backup',{});s.notify(s.t('环境清单已备份','Package inventory backed up'))})"><Save :size="15"/>{{s.t('备份环境清单','Back up inventory')}}</button></div><p v-if="snapshot" class="muted">{{snapshot.file}}</p><div class="package-table"><div v-for="p in packages" :key="p.name"><strong>{{p.name}}</strong><code>{{p.version}}</code></div></div></div></details>
  <details class="log-view" open><summary><Terminal :size="16"/>{{s.t('运行与安装日志','Engine & installation log')}}<span>{{s.engine.logs.length}}</span></summary><pre>{{s.engine.logs.join('\n')||s.t('暂时没有日志。启动引擎或运行安装后，日志显示在这里。','Start the engine or installer to see the log.')}}</pre></details></div></details>
 <details v-show="category==='models'" class="card settings-section" open><summary><div class="section-title"><FolderOpen :size="20"/><div><strong>{{s.t('本地模型管理','Local models')}}</strong><small>{{s.t('原版和 2.9B 分别适配，LoRA 按需选择','Original and 2.9B profiles, optional LoRAs')}}</small></div></div><ChevronDown :size="17"/></summary><div class="settings-body"><DownloadCenter/><div class="model-download-row"><article><strong>Anima {{s.t('官方原版','Original')}}</strong><small>Base v1.0</small><div class="button-row"><button class="secondary" @click="s.action(()=>api('models/download',{profile:'original'}))" :disabled="s.install.state==='running'"><Download :size="15"/>{{s.t('下载模型','Download')}}</button><button class="text-button" @click="s.openLink('original')">{{s.t('模型主页','Model page')}}</button></div></article><article><strong>Anima 2.9B</strong><small>Preview v1</small><div class="button-row"><button class="secondary" @click="s.action(()=>api('models/download',{profile:'expanded'}))" :disabled="s.install.state==='running'"><Download :size="15"/>{{s.t('下载模型','Download')}}</button><button class="text-button" @click="s.openLink('expanded')">{{s.t('模型主页','Model page')}}</button></div></article><article><strong>{{s.t('局部重绘模型','Inpaint model')}}</strong><small>遮罩引导与局部物品替换</small><button class="secondary" @click="s.action(()=>api('models/download',{profile:'inpaint'}))" :disabled="s.install.state==='running'"><Download :size="15"/>{{s.t('下载重绘模型','Download inpaint')}}</button></article></div><div v-for="f in folders" :key="f.kind" class="model-folder"><div class="model-folder-title"><div><strong>{{f.title}}</strong><small>{{f.desc}}</small></div><span class="muted">{{s.models[f.kind]?.length||0}} {{s.t('个文件','files')}}</span><button class="secondary" @click="importModel(f.kind)"><Upload :size="14"/>{{s.t('导入','Import')}}</button><button class="secondary" @click="s.openFolder(f.kind)"><FolderOpen :size="14"/>{{s.t('打开文件夹','Open folder')}}</button></div><div class="model-files"><div v-for="name in s.models[f.kind]" :key="name"><code>{{name}}</code><span class="check-state ok">✓</span></div><p v-if="!s.models[f.kind]?.length" class="muted">{{s.t('此目录暂无模型文件','No model files in this folder')}}</p></div></div><button class="secondary" @click="s.action(async()=>{s.models=await api('models');s.notify(s.t('模型列表已刷新；新模型请重启引擎加载','Models refreshed. Restart the engine to load new files.'))})"><RefreshCw :size="15"/>{{s.t('刷新模型列表','Refresh models')}}</button></div></details>
 <section v-show="category==='assistant'" class="card"><div class="card-heading"><strong>提示词助手 · 模型与 API</strong></div><LlmSettings/></section><section v-if="category==='content'" class="card"><div class="card-heading"><strong>成人内容显示设置</strong></div><div class="settings-body"><label class="inline-check"><input type="checkbox" v-model="s.config.adultContentEnabled"/>显示成人内容筛选（可疑 / R18）</label><p class="muted">默认关闭，隐藏 Danbooru 的“可疑 / R18”选项。打开后才显示；“所有”始终可选，会选择当前允许显示的内容类别。</p></div></section><UpdateCenter v-if="category==='updates'" embedded/><FileSettings v-if="category==='files'"/><CacheSettings v-if="category==='storage'"/><OperationGuide v-show="category==='guide'"/>
 <footer v-show="category==='about'" class="developer-card"><div class="brand-mark small">若</div><div class="developer-details"><strong>{{about.name}}</strong><a class="developer-url" :href="about.repository" @click.prevent="s.openLink('project')">{{about.repository}}</a></div><div class="developer-actions"><button class="primary" @click="s.openLink('project')">{{s.t('项目主页','Project on GitHub')}}<ExternalLink :size="14"/></button></div></footer>
</div></div></template>
